-- FullMatch Studio: run the COMPLETE file in the Stocky project's Supabase SQL Editor.
-- Check the selected project and its backup before running. No credentials are needed here.
-- Generated by npm run commerce:schema:sql; do not edit this generated file.
-- Adds schema only: does not enable businesses, infer currency, seed demo data or publish products.
-- One transaction; a failure rolls everything back. Known migrations are safe to run again.
BEGIN;
SET LOCAL search_path = public, pg_catalog;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '45s';

DO $fullmatch_schema$
DECLARE
  table_name text;
  role_name text;
  previous_checksum text;
  table_fingerprint jsonb;
  before_fingerprints jsonb := '{}'::jsonb;
  after_fingerprints jsonb := '{}'::jsonb;
  required_reference record;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('stocky:commerce:migration'));
  IF to_regclass('public.products') IS NULL THEN
    RAISE EXCEPTION 'INVENTORY_FOUNDATION_REQUIRED: select the existing Stocky database';
  END IF;

  FOREACH table_name IN ARRAY ARRAY['products', 'clients', 'proveedores', 'pedidos', 'transactions', 'inventory_operations', 'inventory_movements'] LOOP
    IF to_regclass(format('public.%I', table_name)) IS NOT NULL THEN
      EXECUTE format($fingerprint$
        SELECT jsonb_build_object('count', count(*)::text,
          'hash', md5(COALESCE(string_agg(md5(to_jsonb(t)::text), '' ORDER BY md5(to_jsonb(t)::text)), '')))
        FROM public.%I t
      $fingerprint$, table_name) INTO table_fingerprint;
      before_fingerprints := before_fingerprints || jsonb_build_object(table_name, table_fingerprint);
    END IF;
  END LOOP;

  CREATE TABLE IF NOT EXISTS public.commerce_schema_migrations (
    version INTEGER PRIMARY KEY, checksum TEXT NOT NULL, applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
  );

  -- Migration 1; checksum matches the canonical repository source.
  SELECT checksum INTO previous_checksum FROM public.commerce_schema_migrations WHERE version = 1;
  IF FOUND THEN
    IF NOT (previous_checksum = ANY(ARRAY['92228aa6ff5d490c3e678d589db3f22d2fe6857177c8497dab59b9e830a1a6a6', '08a2cf4cceb0b759d3a0533eeed90cceeb95b4166eddeef38f3ec15c5f950b68'])) THEN
      RAISE EXCEPTION 'MIGRATION_CHECKSUM_MISMATCH: version 1';
    END IF;
  ELSE
    -- Explicit, additive migration. Never imported by HTTP bootstrap.
    CREATE UNIQUE INDEX IF NOT EXISTS idx_products_owner_id_commerce ON products(owner_phone,id);

    CREATE TABLE inventory_money_policies (
      owner_phone TEXT PRIMARY KEY,
      currency TEXT NOT NULL CHECK(currency IN ('ARS','UYU','USD')),
      storage_unit TEXT NOT NULL CHECK(storage_unit='major_integer'),
      fraction_digits SMALLINT NOT NULL CHECK(fraction_digits=2),
      revision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0),
      confirmed_by TEXT NOT NULL, confirmed_at TIMESTAMPTZ NOT NULL,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    );

    CREATE TABLE commerce_profiles (
      owner_phone TEXT PRIMARY KEY, id UUID NOT NULL UNIQUE,
      brand_name TEXT NOT NULL CHECK(length(btrim(brand_name)) BETWEEN 1 AND 80),
      sales_whatsapp TEXT CHECK(sales_whatsapp IS NULL OR sales_whatsapp ~ '^[0-9]{8,15}$'),
      brand_preset TEXT NOT NULL DEFAULT 'fullmatch_v1' CHECK(brand_preset='fullmatch_v1'),
      enabled BOOLEAN NOT NULL DEFAULT false,
      revision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0), created_by TEXT NOT NULL,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    );

    CREATE TABLE commercial_products (
      owner_phone TEXT NOT NULL REFERENCES commerce_profiles(owner_phone), id UUID NOT NULL,
      title TEXT NOT NULL CHECK(length(btrim(title)) BETWEEN 1 AND 120),
      description TEXT NOT NULL DEFAULT '' CHECK(length(description)<=4000),
      team_key TEXT CHECK(team_key IS NULL OR team_key ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
      team_name TEXT CHECK(team_name IS NULL OR length(btrim(team_name)) BETWEEN 1 AND 100),
      team_kind TEXT CHECK(team_kind IN ('club','national_team')),
      season TEXT CHECK(season IS NULL OR season ~ '^[0-9]{4}(/[0-9]{2}([0-9]{2})?)?$'),
      kit_key TEXT CHECK(kit_key IN ('home','away','third','goalkeeper','special')),
      version_key TEXT CHECK(version_key IN ('fan','player')),
      sleeve_key TEXT CHECK(sleeve_key IN ('short','long','sleeveless')),
      identity_key TEXT CHECK(identity_key IS NULL OR identity_key ~ '^[a-f0-9]{64}$'),
      slug TEXT NOT NULL CHECK(length(slug) BETWEEN 1 AND 120 AND slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
      status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','ready','archived')),
      cover_image_id UUID, revision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0),
      created_by TEXT NOT NULL, updated_by TEXT NOT NULL,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), archived_at TIMESTAMPTZ,
      PRIMARY KEY(owner_phone,id), UNIQUE(owner_phone,slug),
      CHECK((status='archived')=(archived_at IS NOT NULL)),
      CHECK(status<>'ready' OR (identity_key IS NOT NULL AND team_key IS NOT NULL AND team_name IS NOT NULL
        AND team_kind IS NOT NULL AND season IS NOT NULL AND kit_key IS NOT NULL AND version_key IS NOT NULL AND sleeve_key IS NOT NULL))
    );
    CREATE UNIQUE INDEX idx_commercial_products_identity ON commercial_products(owner_phone,identity_key)
      WHERE identity_key IS NOT NULL AND status<>'archived';
    CREATE INDEX idx_commercial_products_list ON commercial_products(owner_phone,status,updated_at DESC,id DESC);

    CREATE TABLE commercial_product_skus (
      owner_phone TEXT NOT NULL, commercial_product_id UUID NOT NULL, sku_id TEXT NOT NULL,
      identity_fingerprint_at_link TEXT NOT NULL,
      sort_order INTEGER NOT NULL DEFAULT 0 CHECK(sort_order>=0), linked_by TEXT NOT NULL,
      linked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      PRIMARY KEY(owner_phone,commercial_product_id,sku_id), UNIQUE(owner_phone,sku_id),
      FOREIGN KEY(owner_phone,commercial_product_id) REFERENCES commercial_products(owner_phone,id),
      FOREIGN KEY(owner_phone,sku_id) REFERENCES products(owner_phone,id)
    );

    CREATE TABLE commercial_product_images (
      owner_phone TEXT NOT NULL, id UUID NOT NULL, commercial_product_id UUID NOT NULL,
      status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','ready','failed','deleted')),
      source_sha256 TEXT NOT NULL CHECK(source_sha256 ~ '^[a-f0-9]{64}$'),
      source_size_bytes BIGINT NOT NULL CHECK(source_size_bytes>0 AND source_size_bytes<=12582912),
      master_key TEXT, thumbnail_key TEXT, master_sha256 TEXT,
      mime_type TEXT, width INTEGER, height INTEGER, stored_size_bytes BIGINT,
      alt_text TEXT NOT NULL DEFAULT '' CHECK(length(alt_text)<=300),
      sort_order INTEGER NOT NULL DEFAULT 0 CHECK(sort_order>=0),
      focal_x NUMERIC NOT NULL DEFAULT 0.5 CHECK(focal_x>=0 AND focal_x<=1),
      focal_y NUMERIC NOT NULL DEFAULT 0.5 CHECK(focal_y>=0 AND focal_y<=1),
      revision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0), attempt_id UUID, processing_started_at TIMESTAMPTZ,
      upload_expires_at TIMESTAMPTZ NOT NULL, product_identity_at_start TEXT, error_code TEXT,
      created_by TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      deleted_at TIMESTAMPTZ, purged_at TIMESTAMPTZ,
      PRIMARY KEY(owner_phone,id), UNIQUE(owner_phone,commercial_product_id,id),
      FOREIGN KEY(owner_phone,commercial_product_id) REFERENCES commercial_products(owner_phone,id),
      CHECK(status<>'ready' OR (master_key IS NOT NULL AND thumbnail_key IS NOT NULL AND master_sha256 IS NOT NULL
        AND mime_type IS NOT NULL AND width IS NOT NULL AND height IS NOT NULL AND stored_size_bytes IS NOT NULL
        AND width>0 AND height>0 AND stored_size_bytes>0)),
      CHECK(status<>'processing' OR (attempt_id IS NOT NULL AND processing_started_at IS NOT NULL)),
      CHECK(master_sha256 IS NULL OR master_sha256 ~ '^[a-f0-9]{64}$'),
      CHECK((status='deleted')=(deleted_at IS NOT NULL))
    );
    CREATE INDEX idx_commercial_images_gallery ON commercial_product_images(owner_phone,commercial_product_id,status,sort_order,id);
    CREATE INDEX idx_commercial_images_maintenance ON commercial_product_images(status,updated_at);
    ALTER TABLE commercial_products ADD CONSTRAINT commercial_product_cover_fk
      FOREIGN KEY(owner_phone,id,cover_image_id) REFERENCES commercial_product_images(owner_phone,commercial_product_id,id);

    CREATE TABLE commercial_operations (
      owner_phone TEXT NOT NULL REFERENCES commerce_profiles(owner_phone), operation_id UUID NOT NULL,
      actor_id TEXT NOT NULL, operation_type TEXT NOT NULL, entity_id UUID,
      request_hash TEXT NOT NULL CHECK(request_hash ~ '^[a-f0-9]{64}$'),
      request_json JSONB NOT NULL, result_json JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      PRIMARY KEY(owner_phone,operation_id)
    );
    CREATE INDEX idx_commercial_operations_entity ON commercial_operations(owner_phone,entity_id,created_at DESC);

    INSERT INTO public.commerce_schema_migrations(version, checksum) VALUES (1, '92228aa6ff5d490c3e678d589db3f22d2fe6857177c8497dab59b9e830a1a6a6');
  END IF;


  -- Migration 2; checksum matches the canonical repository source.
  SELECT checksum INTO previous_checksum FROM public.commerce_schema_migrations WHERE version = 2;
  IF FOUND THEN
    IF NOT (previous_checksum = ANY(ARRAY['83d50ed4aa31b43ece382abd23c2eae70d2a87f65059044afbc852e9f29f0aa2', '6aa1fabc8be1be057c31445f47a177ad87f29ef8b7962d4827854998f36d52e2'])) THEN
      RAISE EXCEPTION 'MIGRATION_CHECKSUM_MISMATCH: version 2';
    END IF;
  ELSE
    CREATE TABLE commerce_catalogs (
      owner_phone TEXT PRIMARY KEY REFERENCES commerce_profiles(owner_phone), id UUID NOT NULL UNIQUE,
      slug TEXT NOT NULL UNIQUE CHECK(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' AND length(slug) BETWEEN 3 AND 64),
      public_enabled BOOLEAN NOT NULL DEFAULT false, revision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0),
      created_by TEXT NOT NULL, updated_by TEXT NOT NULL,
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
    );
    CREATE TABLE commercial_publications (
      owner_phone TEXT NOT NULL, commercial_product_id UUID NOT NULL,
      status TEXT NOT NULL DEFAULT 'hidden' CHECK(status IN ('hidden','published')),
      revision BIGINT NOT NULL DEFAULT 1 CHECK(revision>0), reason TEXT NOT NULL CHECK(length(reason) BETWEEN 1 AND 500),
      updated_by TEXT NOT NULL, published_at TIMESTAMPTZ, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      PRIMARY KEY(owner_phone,commercial_product_id),
      CHECK(status<>'published' OR published_at IS NOT NULL),
      FOREIGN KEY(owner_phone,commercial_product_id) REFERENCES commercial_products(owner_phone,id)
    );
    CREATE INDEX idx_commercial_publications_visible ON commercial_publications(owner_phone,commercial_product_id) WHERE status='published';

    INSERT INTO public.commerce_schema_migrations(version, checksum) VALUES (2, '83d50ed4aa31b43ece382abd23c2eae70d2a87f65059044afbc852e9f29f0aa2');
  END IF;


  -- Migration 3; checksum matches the canonical repository source.
  SELECT checksum INTO previous_checksum FROM public.commerce_schema_migrations WHERE version = 3;
  IF FOUND THEN
    IF NOT (previous_checksum = ANY(ARRAY['14924046890a5c7e76abc06debcf64cfe044a529faa9d8dac2dd79a6ac9c68cd', '7ec22c7f3cc43af07936595ea8b937947e275a71e3ae6422e3edfbdba341962d'])) THEN
      RAISE EXCEPTION 'MIGRATION_CHECKSUM_MISMATCH: version 3';
    END IF;
  ELSE
    CREATE INDEX idx_commercial_operations_library ON commercial_operations(owner_phone,operation_type,created_at DESC,operation_id DESC);

    INSERT INTO public.commerce_schema_migrations(version, checksum) VALUES (3, '14924046890a5c7e76abc06debcf64cfe044a529faa9d8dac2dd79a6ac9c68cd');
  END IF;


  -- Migration 4; checksum matches the canonical repository source.
  SELECT checksum INTO previous_checksum FROM public.commerce_schema_migrations WHERE version = 4;
  IF FOUND THEN
    IF NOT (previous_checksum = ANY(ARRAY['fcfa343f83cca625feeb2066feaf46f24a176068a31e1f5b69b1f0fae9fbaac8', '50df79e5cab3a2ad21d6d34aa050d1326bfeb81b40bda39c5ef5846ec91cf5b8'])) THEN
      RAISE EXCEPTION 'MIGRATION_CHECKSUM_MISMATCH: version 4';
    END IF;
  ELSE
    ALTER TABLE commerce_profiles ADD COLUMN appearance JSONB NOT NULL DEFAULT '{}'::jsonb
      CHECK (jsonb_typeof(appearance) = 'object');

    CREATE TABLE commerce_brand_assets (
      owner_phone TEXT NOT NULL REFERENCES commerce_profiles(owner_phone),
      id UUID NOT NULL,
      kind TEXT NOT NULL CHECK (kind IN ('logo', 'cover')),
      mime_type TEXT NOT NULL CHECK (mime_type IN ('image/png', 'image/jpeg')),
      content BYTEA NOT NULL CHECK (octet_length(content) BETWEEN 1 AND 1048576),
      created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
      PRIMARY KEY (owner_phone, id)
    );
    ALTER TABLE commerce_brand_assets ENABLE ROW LEVEL SECURITY;
    REVOKE ALL ON commerce_brand_assets FROM PUBLIC;
    DO $$ DECLARE role_name TEXT; BEGIN
      FOR role_name IN SELECT rolname FROM pg_roles WHERE rolname IN ('anon', 'authenticated') LOOP
        EXECUTE format('REVOKE ALL ON commerce_brand_assets FROM %I', role_name);
      END LOOP;
    END $$;

    INSERT INTO public.commerce_schema_migrations(version, checksum) VALUES (4, 'fcfa343f83cca625feeb2066feaf46f24a176068a31e1f5b69b1f0fae9fbaac8');
  END IF;


  -- Migration 5; checksum matches the canonical repository source.
  SELECT checksum INTO previous_checksum FROM public.commerce_schema_migrations WHERE version = 5;
  IF FOUND THEN
    IF NOT (previous_checksum = ANY(ARRAY['219ccabb12b6f5eed55c11d7382a94c9fa970f089bd05c669d1851fe2fc21860', '16fd1ddae651ee45d0937103ab7f9d608fcadb94ffe7f7744e08efb9a7cce2ba'])) THEN
      RAISE EXCEPTION 'MIGRATION_CHECKSUM_MISMATCH: version 5';
    END IF;
  ELSE
    -- Preserve all existing rows and sports identity fields/indexes. Only remove
    -- the legacy requirement that every ready product have a football identity.
    DO $$ DECLARE legacy_name TEXT; BEGIN
      SELECT conname INTO STRICT legacy_name FROM pg_constraint
        WHERE conrelid='public.commercial_products'::regclass AND contype='c'
          AND pg_get_constraintdef(oid) LIKE '%ready%'
          AND pg_get_constraintdef(oid) LIKE '%identity_key%'
          AND pg_get_constraintdef(oid) LIKE '%team_kind%';
      EXECUTE format('ALTER TABLE public.commercial_products DROP CONSTRAINT %I', legacy_name);
    END $$;
    ALTER TABLE commercial_products ADD CONSTRAINT commercial_products_ready_title
      CHECK(status<>'ready' OR length(btrim(title))>0);

    INSERT INTO public.commerce_schema_migrations(version, checksum) VALUES (5, '219ccabb12b6f5eed55c11d7382a94c9fa970f089bd05c669d1851fe2fc21860');
  END IF;

  FOREACH table_name IN ARRAY ARRAY['inventory_money_policies', 'commerce_profiles', 'commercial_products', 'commercial_product_skus', 'commercial_product_images', 'commercial_operations', 'commerce_catalogs', 'commercial_publications', 'commerce_schema_migrations', 'commerce_brand_assets'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', table_name);
    EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC', table_name);
    FOR role_name IN SELECT rolname FROM pg_roles WHERE rolname IN ('anon', 'authenticated') LOOP
      EXECUTE format('REVOKE ALL ON TABLE public.%I FROM %I', table_name, role_name);
    END LOOP;
  END LOOP;

  FOR required_reference IN SELECT * FROM (VALUES
    ('commercial_products', 'FOREIGNKEY(owner_phone)REFERENCEScommerce_profiles(owner_phone)'),
    ('commercial_products', 'FOREIGNKEY(owner_phone,id,cover_image_id)REFERENCEScommercial_product_images(owner_phone,commercial_product_id,id)'),
    ('commercial_product_skus', 'FOREIGNKEY(owner_phone,commercial_product_id)REFERENCEScommercial_products(owner_phone,id)'),
    ('commercial_product_skus', 'FOREIGNKEY(owner_phone,sku_id)REFERENCESproducts(owner_phone,id)'),
    ('commercial_product_images', 'FOREIGNKEY(owner_phone,commercial_product_id)REFERENCEScommercial_products(owner_phone,id)'),
    ('commercial_operations', 'FOREIGNKEY(owner_phone)REFERENCEScommerce_profiles(owner_phone)'),
    ('commerce_catalogs', 'FOREIGNKEY(owner_phone)REFERENCEScommerce_profiles(owner_phone)'),
    ('commercial_publications', 'FOREIGNKEY(owner_phone,commercial_product_id)REFERENCEScommercial_products(owner_phone,id)')
  ) AS required(table_name, definition) LOOP
    IF NOT EXISTS (
      SELECT 1 FROM pg_constraint k JOIN pg_class c ON c.oid = k.conrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
      WHERE n.nspname = 'public' AND c.relname = required_reference.table_name AND k.contype = 'f'
        AND left(replace(regexp_replace(pg_get_constraintdef(k.oid), '[[:space:]"]', '', 'g'), 'public.', ''),
          length(required_reference.definition)) = required_reference.definition
    ) THEN RAISE EXCEPTION 'COMMERCE_SCHEMA_NOT_READY: missing reference on %', required_reference.table_name;
    END IF;
  END LOOP;
  IF EXISTS (
    SELECT 1 FROM pg_roles r CROSS JOIN pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relname = ANY(ARRAY['inventory_money_policies', 'commerce_profiles', 'commercial_products', 'commercial_product_skus', 'commercial_product_images', 'commercial_operations', 'commerce_catalogs', 'commercial_publications', 'commerce_schema_migrations', 'commerce_brand_assets'])
      AND r.rolname IN ('anon', 'authenticated')
      AND (has_table_privilege(r.oid, c.oid, 'SELECT') OR has_table_privilege(r.oid, c.oid, 'INSERT')
        OR has_table_privilege(r.oid, c.oid, 'UPDATE') OR has_table_privilege(r.oid, c.oid, 'DELETE')
        OR has_table_privilege(r.oid, c.oid, 'TRUNCATE') OR has_table_privilege(r.oid, c.oid, 'REFERENCES')
        OR has_table_privilege(r.oid, c.oid, 'TRIGGER'))
  ) THEN RAISE EXCEPTION 'COMMERCE_SCHEMA_NOT_READY: API roles retain access'; END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_index i WHERE i.indexrelid = to_regclass('public.idx_commercial_operations_library')
      AND i.indisvalid AND position('(owner_phone,operation_type,created_atDESC,operation_idDESC)'
        in replace(pg_get_indexdef(i.indexrelid), ' ', '')) > 0
  ) THEN RAISE EXCEPTION 'CONTENT_SCHEMA_NOT_READY'; END IF;

  FOREACH table_name IN ARRAY ARRAY['products', 'clients', 'proveedores', 'pedidos', 'transactions', 'inventory_operations', 'inventory_movements'] LOOP
    IF to_regclass(format('public.%I', table_name)) IS NOT NULL THEN
      EXECUTE format($fingerprint$
        SELECT jsonb_build_object('count', count(*)::text,
          'hash', md5(COALESCE(string_agg(md5(to_jsonb(t)::text), '' ORDER BY md5(to_jsonb(t)::text)), '')))
        FROM public.%I t
      $fingerprint$, table_name) INTO table_fingerprint;
      after_fingerprints := after_fingerprints || jsonb_build_object(table_name, table_fingerprint);
    END IF;
  END LOOP;

  IF before_fingerprints IS DISTINCT FROM after_fingerprints THEN
    RAISE EXCEPTION 'MIGRATION_DATA_MISMATCH: existing inventory data changed; rolling back';
  END IF;
END
$fullmatch_schema$;
COMMIT;

-- Success: versions 1, 2, 3 and 4. Business/profile enablement is a separate step.
SELECT version, applied_at FROM public.commerce_schema_migrations
WHERE version IN (1, 2, 3, 4) ORDER BY version;
